CREATE OR REPLACE FUNCTION public.purge_expired_chats_bounded() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids text[]; removed integer; days_value integer; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT p.days INTO days_value FROM public.retention_policies p WHERE p.data_type='chats'; days_value := COALESCE(days_value, 90); LOCK TABLE public.suggestion_requests IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.live_chats IN SHARE ROW EXCLUSIVE MODE; SELECT array_agg(candidate_id) INTO ids FROM public.retention_candidates('chats',days_value,100); DELETE FROM public.live_chats WHERE id::text=ANY(ids); GET DIAGNOSTICS removed=ROW_COUNT; IF removed>0 THEN INSERT INTO public.admin_activity(actor_id,actor_email,action,target) VALUES('00000000-0000-0000-0000-000000000000','system','retention.chat_expiry','chats count='||removed::text); END IF; RETURN removed; END $$;
REVOKE ALL ON FUNCTION public.purge_expired_chats_bounded() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_expired_chats_bounded() TO service_role;